class Timer:
    def __enter__(self):
        self.items = 0
        return self
    def __exit__(self, exc_type, exc, tb):
        print("выход:", exc_type.__name__ if exc_type else "без ошибок")

with Timer() as t:
    t.items = 5
print(t.items)

